package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"plain", "Ada", "ada"},
		{"upper", "ADA", "ada"},
		{"single space", "Ada Lovelace", "ada-lovelace"},
		{"surrounding whitespace", "  Ada  ", "ada"},
		{"collapsed whitespace", "Ada   Lovelace", "ada-lovelace"},
		{"tabs and newlines", "\tAda\nLovelace ", "ada-lovelace"},
		{"empty", "", ""},
		{"blank", "   ", ""},
		{"hyphen kept", "Anne-Marie", "anne-marie"},
		{"leading and trailing hyphen", "-Ada-", "ada"},
		{"hyphen run collapsed", "Ada - Lovelace", "ada-lovelace"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

